// Genuary #16: Generative palette


#define rot(a) mat2(cos(a), sin(a), -sin(a), cos(a))
#define PI acos(-1.)
#define noi(u) textureLod(iChannel0, u, 0.).x

float plasma (vec2 uv)
{ return sin(dot(sin(uv+iTime), cos(uv.yx*PI-iTime))*PI*2.-iTime)*.5+.5; }

float box (vec3 p , vec3 c)
{
    vec3 q = abs(p)-c;
    return min(0., max(q.x, max(q.y, q.z)))+length(max(q, 0.));
}

vec3 SDF (vec3 p)
{
    p.yz *= rot(-atan(1./sqrt(2.)));
    p.xz *= rot(PI/4.);

    p.x += iTime;

    vec2 id = floor(p.xz/2.);
    float d;
    if(noi(id*.47) < .5)
    {
        float per = 2., size = .7;
        p.xz = mod(p.xz, per)-per*.5;

        d = box(p, vec3(size));
        d = max(abs(abs(abs(d)-.1)-.05)-.01, p.y-size*.5);
    }
    else
    {
        id = floor(p.xz);
        float per = 1., size = .25;
        p.xz = mod(p.xz, per)-per*.5;

        d = box(p, vec3(size));
        d = max(abs(abs(abs(d)-.1)-.05)-.01, p.y-size*.65);
    } 

    d = min(d, abs(p.y+1.));
    return vec3(d, id);
}

vec3 gn (vec3 p)
{
    vec2 eps= vec2(0.01, 0.);
    return normalize(SDF(p).x-vec3(SDF(p-eps.xyy).x,SDF(p-eps.yxy).x,SDF(p-eps.yyx).x));
}

float AO (vec3 p, vec3 n, float e)
{ return clamp(SDF(p+e*n).x/e, 0., 1.); }

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = (fragCoord-iResolution.xy/2.) / iResolution.y;

    vec3 ro = vec3(uv*10., -30.), rd=vec3(0.,0.,1.), p=ro,
    col=vec3(0.), l=normalize(vec3(1., 2., -1.));

    vec3 did;
    for (float i= 0.; i<100.; i++)
    {
        did = SDF(p);
        if (did.x < 0.01)
        {
            break;
        }
        p += did.x*rd*.8;
    }

    vec3 n = gn(p); 
    float pla = plasma(did.yz);
    col = vec3(pla*.25, pla*.7, .9);  
    float ao = AO(p,n, 0.1) + AO(p,n, 0.25) + AO(p,n, 0.15);   
    col /= ao*.33;

    fragColor = vec4(sqrt(clamp(col, 0., 1.)),1.0);
}
